                    "start_time": f"{self._EVENT_DATE} {self._PROPOSED_TIME_2}",
                    "end_time": f"{self._EVENT_DATE} {self._END_TIME}",
                },
            ),
        ]

    def utility(
        self,
        model_output: str,
        pre_environment: WorkspaceEnvironment,
        post_environment: WorkspaceEnvironment,
